package com.tencent.weknora.security;

import jakarta.servlet.http.HttpServletRequest;
import java.time.format.DateTimeFormatterBuilder;
import java.util.*;
import org.springframework.dao.DataAccessException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;

@RestController
public final class TenantInvitationController {
    private final TenantInvitationService service;
    private final TenantMemberService members;
    private final AuthRepository repository;
    private final SecuritySettings settings;
    private final JdbcTemplate jdbc;
    public TenantInvitationController(TenantInvitationService service,TenantMemberService members,AuthRepository repository,SecuritySettings settings,JdbcTemplate jdbc){this.service=service;this.members=members;this.repository=repository;this.settings=settings;this.jdbc=jdbc;}
    @GetMapping("/api/v1/tenants/{tenantId}/invitations")
    public Map<String,Object> tenantList(HttpServletRequest request,@PathVariable String tenantId,@RequestParam(name="include_terminal",required=false)String terminal,@RequestParam(required=false)String page,@RequestParam(name="page_size",required=false)String pageSize){AuthContext auth=CurrentAuth.get(request);long tenant=authorize(auth,tenantId,"viewer"),p=positive(page,1,"page must be a positive integer"),s=positive(pageSize,20,"page_size must be between 1 and 100");if(s>100)throw invalid("page_size must be between 1 and 100");
        try{var result=service.list(tenant,"true".equalsIgnoreCase(terminal),p,s);List<Map<String,Object>> dto=new ArrayList<>();for(var row:result.rows())dto.add(project(row,false,AuthContext.level(auth.role())>=AuthContext.level("owner")));return ok(Map.of("invitations",dto,"total",result.total(),"page",p,"page_size",s));}catch(DataAccessException ex){throw internal("failed to list invitations");}
    }
    @PostMapping("/api/v1/tenants/{tenantId}/invitations") @ResponseStatus(HttpStatus.CREATED)
    public Map<String,Object> create(HttpServletRequest request,@PathVariable String tenantId) throws java.io.IOException {AuthContext auth=CurrentAuth.get(request);long tenant=authorize(auth,tenantId,"owner");Map<String,Object> body=InvitationRequestDecoder.decode(request.getInputStream().readAllBytes(),InvitationRequestDecoder.Schema.CREATE);String role=role(body),email=field(body,"email","invalid request body"),message=optional(body,"message");Map<String,Object> user;try{user=repository.anyUserByEmail(AuthPreferences.trimGoSpace(email));}catch(DataAccessException ex){throw internal("failed to look up user");}if(user==null)throw new ApiException(404,"NOT_FOUND","user with this email is not registered; ask them to sign up first").withAppCode(1003);
        if(settings.autoAcceptInvitation()){var response=members.add(auth,tenantId,Map.of("email",AuthPreferences.trimGoSpace(email),"role",role));service.reconcile(tenant,AuthRepository.string(user,"id"));adopt( AuthRepository.string(user,"id"),tenant,"member added but default workspace update failed");return response;}
        try{return ok(project(service.create(auth,tenant,AuthRepository.string(user,"id"),role,message,false),false,false));}catch(DataAccessException ex){throw internal("failed to create invitation");}
    }
    @PostMapping("/api/v1/tenants/{tenantId}/invite-links") @ResponseStatus(HttpStatus.CREATED)
    public Map<String,Object> share(HttpServletRequest request,@PathVariable String tenantId) throws java.io.IOException {AuthContext auth=CurrentAuth.get(request);long tenant=authorize(auth,tenantId,"owner");Map<String,Object> body=InvitationRequestDecoder.decode(request.getInputStream().readAllBytes(),InvitationRequestDecoder.Schema.SHARE);String role=role(body);try{return ok(project(service.create(auth,tenant,"",role,optional(body,"message"),true),false,true));}catch(DataAccessException ex){throw internal("failed to create share link");}}
    @DeleteMapping("/api/v1/tenants/{tenantId}/invitations/{invId}")
    public Map<String,Object> revoke(HttpServletRequest request,@PathVariable String tenantId,@PathVariable String invId){AuthContext auth=CurrentAuth.get(request);long tenant=authorize(auth,tenantId,"owner"),id=id(invId);try{service.revoke(auth,tenant,id);return Map.of("success",true);}catch(DataAccessException ex){throw internal("failed to revoke invitation");}}
    @GetMapping("/api/v1/me/invitations")
    public Map<String,Object> inbox(HttpServletRequest request,@RequestParam(name="include_terminal",required=false)String terminal){AuthContext auth=human(request);try{var rows=service.inbox(auth.userId(),"true".equalsIgnoreCase(terminal));List<Map<String,Object>> dto=new ArrayList<>();for(var row:rows)dto.add(project(row,true,false));return ok(Map.of("invitations",dto,"total",dto.size()));}catch(DataAccessException ex){throw internal("failed to list invitations");}}
    @GetMapping("/api/v1/me/invitations/pending-count")
    public Map<String,Object> count(HttpServletRequest request){AuthContext auth=human(request);try{return ok(Map.of("pending_count",service.count(auth.userId())));}catch(DataAccessException ex){throw internal("failed to count pending invitations");}}
    @PostMapping("/api/v1/me/invitations/{invId}/accept")
    public Map<String,Object> accept(HttpServletRequest request,@PathVariable String invId){AuthContext auth=human(request);try{var member=service.accept(auth,id(invId));adopt(auth.userId(),AuthRepository.number(member,"tenant_id"),"invitation accepted but default workspace update failed");return ok(Map.of("membership",membership(member)));}catch(DataAccessException ex){throw internal("failed to accept invitation");}}
    @PostMapping("/api/v1/me/invitations/{invId}/decline")
    public Map<String,Object> decline(HttpServletRequest request,@PathVariable String invId){AuthContext auth=human(request);try{service.decline(auth,id(invId));return Map.of("success",true);}catch(DataAccessException ex){throw internal("failed to decline invitation");}}
    @PostMapping("/api/v1/me/invitations/accept-by-token")
    public Map<String,Object> acceptToken(HttpServletRequest request) throws java.io.IOException {AuthContext auth=human(request);Map<String,Object> body=InvitationRequestDecoder.decode(request.getInputStream().readAllBytes(),InvitationRequestDecoder.Schema.ACCEPT);String token=AuthPreferences.trimGoSpace(field(body,"token","token is required"));if(token.isEmpty())throw invalid("token is required");try{var member=service.acceptToken(auth,token);long tenant=AuthRepository.number(member,"tenant_id");adopt(auth.userId(),tenant,"invitation accepted but default workspace update failed");var workspace=repository.tenant(tenant);return ok(Map.of("membership",membership(member),"tenant_name",workspace==null?"":AuthRepository.string(workspace,"name")));}catch(DataAccessException ex){throw internal("failed to accept invitation");}}
    @PostMapping("/api/v1/auth/invitations/lookup")
    public Map<String,Object> lookup(HttpServletRequest request) throws java.io.IOException {Map<String,Object> body=InvitationRequestDecoder.decode(request.getInputStream().readAllBytes(),InvitationRequestDecoder.Schema.LOOKUP);String token=AuthPreferences.trimGoSpace(field(body,"token","token is required"));if(token.isEmpty())throw invalid("token is required");Map<String,Object> inv;try{inv=service.lookup(token);}catch(DataAccessException ex){throw gone();}long tenant=AuthRepository.number(inv,"tenant_id");String name="";try{var workspace=repository.tenant(tenant);if(workspace!=null)name=AuthRepository.string(workspace,"name");}catch(DataAccessException ignored){}Map<String,Object> dto=new LinkedHashMap<>();dto.put("tenant_id",tenant);if(!name.isEmpty())dto.put("tenant_name",name);dto.put("role",AuthRepository.string(inv,"role"));dto.put("expires_at",new DateTimeFormatterBuilder().appendInstant(0).toFormatter(Locale.ROOT).format(AuthRepository.instant(inv.get("expires_at"))));return ok(dto);}
    private Map<String,Object> project(Map<String,Object> row,boolean includeTenant,boolean showLink){Map<String,Map<String,Object>> users=new HashMap<>();Map<Long,Map<String,Object>> tenants=new HashMap<>();try{for(var user:jdbc.queryForList("SELECT id,username,email FROM users WHERE deleted_at IS NULL AND (id=? OR id=?)",AuthRepository.string(row,"invitee_user_id"),AuthRepository.string(row,"invited_by")))users.put(AuthRepository.string(user,"id"),user);}catch(DataAccessException ignored){}if(includeTenant)try{var rows=jdbc.queryForList("SELECT id,name FROM tenants WHERE id=? AND deleted_at IS NULL",AuthRepository.number(row,"tenant_id"));if(!rows.isEmpty())tenants.put(AuthRepository.number(row,"tenant_id"),rows.getFirst());}catch(DataAccessException ignored){}return TenantInvitationCodec.project(row,users,tenants,showLink,settings.frontendBaseUrl(),settings.environment().getProperty("FRONTEND_BASE_URL"));}
    private void adopt(String user,long tenant,String failure){try{var rows=jdbc.queryForList("SELECT tenant_id FROM users WHERE id=? AND deleted_at IS NULL",user);if(!rows.isEmpty()&&AuthRepository.number(rows.getFirst(),"tenant_id")==0)repository.saveHomeTenant(user,tenant);}catch(DataAccessException ex){throw internal(failure);}}
    private static Map<String,Object> membership(Map<String,Object> row){return Map.of("tenant_id",AuthRepository.number(row,"tenant_id"),"role",AuthRepository.string(row,"role"),"status",AuthRepository.string(row,"status"),"joined_at",new DateTimeFormatterBuilder().appendInstant(-1).toFormatter(Locale.ROOT).format(AuthRepository.instant(row.get("joined_at"))));}
    private static AuthContext human(HttpServletRequest request){AuthContext auth=CurrentAuth.get(request);if(auth.isApiKey())throw new ApiException(403,"FORBIDDEN","Forbidden: API key route access denied");if(auth.userId().isEmpty())throw new ApiException(401,"UNAUTHORIZED","caller user id missing from context").withAppCode(1001);return auth;}
    private static long authorize(AuthContext auth,String raw,String role){if(!AuthPreferences.trimGoSpace(raw).matches("[0-9]+"))throw invalid("workspace id must be a positive integer");long tenant=positive(raw,0,"workspace id must be a positive integer");if(tenant==0)throw invalid("workspace id must be a positive integer");if(auth.tenantId()==0||tenant!=auth.tenantId()&&!auth.crossTenantSuperuser())throw new ApiException(403,"FORBIDDEN","Access denied: URL workspace does not match the active workspace").withAppCode(1002);if(auth.isApiKey())auth.requireCapability("manage_members");else auth.requireRole(role);return tenant;}
    private static long id(String raw){String text=AuthPreferences.trimGoSpace(raw==null?"":raw);if(text.isEmpty())throw invalid("invitation id is required");if(!text.matches("[0-9]+"))throw invalid("invitation id must be a positive integer");return positive(text,0,"invitation id must be a positive integer");}
    private static long positive(String raw,long fallback,String error){if(raw==null||AuthPreferences.trimGoSpace(raw).isEmpty())return fallback;try{long value=Long.parseLong(AuthPreferences.trimGoSpace(raw));if(value<1)throw new NumberFormatException();return value;}catch(NumberFormatException ex){throw invalid(error);}}
    private static String role(Map<String,Object> body){String role=field(body,"role","invalid request body");if(AuthContext.level(role)==0)throw invalid("role must be one of owner/admin/contributor/viewer");return role;}
    private static String field(Map<String,Object> body,String key,String error){if(body!=null&&body.get(key) instanceof String text&&!text.isEmpty())return text;throw invalid(error);}
    private static String optional(Map<String,Object> body,String key){if(!body.containsKey(key)||body.get(key)==null)return "";if(body.get(key) instanceof String text)return text;throw invalid("invalid request body");}
    private static Map<String,Object> ok(Object data){return Map.of("success",true,"data",data);}
    private static ApiException invalid(String text){return new ApiException(400,"INVALID_REQUEST",text).withAppCode(1010);}
    private static ApiException gone(){return new ApiException(410,"NOT_FOUND","invitation link is invalid or has been revoked").withAppCode(1003);}
    private static ApiException internal(String text){return new ApiException(500,"INTERNAL_ERROR",text).withAppCode(1007).withDetails("Invitation storage operation failed");}
}
